def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.201.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.200.0"' not in init:
        sys.exit("ABORT: not at v3.200.0.")
    if "purchase_invoice" not in data:
        sys.exit("ABORT: purchase_invoice module not found in data file.")

    problems = _validate("PROC7", LESSONS_P7, QUESTIONS_P7, 10)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_P7))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — PROC7 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_P7)
    print(f"PROC 7 v3: {len(LESSONS_P7)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_P7):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["purchase_invoice"]["lessons"] = LESSONS_P7
    data["purchase_invoice"]["questions"] = bank
    data["purchase_invoice"]["desc"] = ("The Purchase Invoice, the three-way match, and the payables machinery in ZhiftERP: the field walk — exact supplier numbering, computed due dates, entry as claimed, and the hold facility; the three comparisons — billed not exceeding accepted, invoice rates equal to order rates with the pairing read, and the tax and arithmetic checks; the exception taxonomy with its lanes and the closes-with-a-document rule; posting effects — the payable, received-not-billed clearing, input VAT, and the due-date machinery; the weekly payment run on terms with line-by-line allocation, withholding at payment with the remittance calendar, and the verified-account rule; debit notes, credit notes, and replacement resolutions with the claim-to-clearing reconciliation; and the six payables reads including the monthly statement reconciliation.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.200.0"', '"3.201.0"'))
    print("  data: PROCUREMENT 7 lessons + bank REPLACED (style v3, textbook manual register)")
    print("wrote __version__ -> 3.201.0")


if __name__ == "__main__":
    main()
